# shellcheck shell=bash
# strict-mode: opt-out sourced library; it must not change the caller's shell options
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-08
#
# git_isolate [dir]: make every later git call in this shell read only a
# throwaway config (#4664).
#
# Tests that create commits in fixture repos otherwise inherit the developer's
# global config. With commit.gpgsign=true and an ssh signer such as 1Password,
# a locked signer fails the commit ("failed to write commit object"), so the
# result depends on the machine, not the code. The same isolation also keeps a
# global core.hooksPath or init.templateDir out of the fixture repos. Source
# this file and call git_isolate once, before the first git command:
#
#   source "$REPO_ROOT/tests/fixtures/git-isolate.sh"
#   git_isolate "$WORK"
#
# The config lives in <dir> (or a new temp dir), so the test's own cleanup
# removes it.

git_isolate() {
  local base="${1:-}"
  if [[ -z "${base}" ]]; then
    base="$(mktemp -d "${TMPDIR:-/tmp}/ork-git-isolate.XXXXXX")"
  fi
  export GIT_CONFIG_GLOBAL="${base}/git-isolate.gitconfig"
  export GIT_CONFIG_NOSYSTEM=1
  printf '[user]\n\tname = ork-test\n\temail = ork-test@example.invalid\n[commit]\n\tgpgsign = false\n[tag]\n\tgpgsign = false\n' \
    > "${GIT_CONFIG_GLOBAL}"
}
